diff --git a/broker/egress/holderapi.go b/broker/egress/holderapi.go
new file mode 100644
index 000000000..ffeb2d645
--- /dev/null
+++ b/broker/egress/holderapi.go
@@ -0,0 +1,61 @@
+package egress
+
+import (
+	"net/http"
+	"time"
+
+	"github.com/ghbmrk/agentos/broker/netguard"
+)
+
+// What a holder process (SIM-split, package holder) shares with the proxy:
+// it checks the same declaration, forwards the same headers, swaps the
+// same exchange shape, and dials through the same address policy.
+
+// Validate checks the declaration, as New does.
+func (a Adapter) Validate() error { return a.validate() }
+
+// Match returns the declared operation that method and path satisfy.
+func (a Adapter) Match(method, path string) (Operation, bool) { return a.match(method, path) }
+
+// ForwardedRequestHeaders are the request headers the proxy forwards for a.
+func (a Adapter) ForwardedRequestHeaders() []string {
+	return append(append([]string(nil), baseRequestHeaders...), a.RequestHeaders...)
+}
+
+// ForwardedResponseHeaders are the response headers the proxy returns for a.
+func (a Adapter) ForwardedResponseHeaders() []string {
+	return append(append([]string(nil), baseResponseHeaders...), a.ResponseHeaders...)
+}
+
+// RefusesLogin reports whether status is one the operation declares as the
+// provider refusing the login (CRED-5t).
+func (op Operation) RefusesLogin(status int) bool { return op.refused(status) }
+
+// SwapResponse checks an exchange response against the operation's
+// declared shape, as the proxy does, and returns the body to forward with
+// every credential swapped and the commit that stores them.
+func (op Operation) SwapResponse(resp *http.Response, adapter string, sw Swapper) ([]byte, func() error, error) {
+	rule := ResponseRule{Fields: append([]Field(nil), op.Response.Fields...)}
+	if err := rule.compile(); err != nil {
+		return nil, nil, err
+	}
+	return rule.swap(resp, adapter, sw)
+}
+
+// Encoded reports whether a response carries any Content-Encoding other
+// than identity, which a redactor cannot read.
+func Encoded(h http.Header) bool { return encoded(h) }
+
+// DefaultTransport is the proxy's default upstream transport: no proxy
+// from the environment, bounded connect, handshake and response-header
+// waits, and every dial and handshake owned by g (DEV-2).
+func DefaultTransport(g *netguard.Policy) *http.Transport {
+	return &http.Transport{
+		DialContext:           g.DialContext,
+		TLSClientConfig:       g.TLSConfig(nil),
+		ForceAttemptHTTP2:     true,
+		TLSHandshakeTimeout:   10 * time.Second,
+		ResponseHeaderTimeout: 10 * time.Minute,
+		IdleConnTimeout:       90 * time.Second,
+	}
+}
diff --git a/broker/egress/holders_test.go b/broker/egress/holders_test.go
new file mode 100644
index 000000000..93ada2a8b
--- /dev/null
+++ b/broker/egress/holders_test.go
@@ -0,0 +1,180 @@
+package egress
+
+import (
+	"bytes"
+	"io"
+	"net/http"
+	"net/http/httptest"
+	"strings"
+	"sync"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/vault"
+)
+
+// REQ: CRED-1, CRED-5, CRED-7, ADP-10
+
+// A proxy whose adapters each have a holder (SIM-split) never reads a
+// secret: it hands the holder the checked request, with no credential, and
+// redacts every vault value from what comes back with a redactor that
+// holds only keyed hashes.
+
+// fakeHolder stands in for an account's holder process.
+type fakeHolder struct {
+	mu    sync.Mutex
+	seen  []*http.Request
+	reply func(r *http.Request) *http.Response
+}
+
+func (f *fakeHolder) RoundTrip(r *http.Request) (*http.Response, error) {
+	f.mu.Lock()
+	f.seen = append(f.seen, r)
+	f.mu.Unlock()
+	if r.Body != nil {
+		io.ReadAll(r.Body)
+	}
+	return f.reply(r), nil
+}
+
+func holderReply(status int, h http.Header, body string) func(*http.Request) *http.Response {
+	return func(r *http.Request) *http.Response {
+		if h == nil {
+			h = http.Header{}
+		}
+		return &http.Response{StatusCode: status, Header: h, Body: io.NopCloser(strings.NewReader(body)), Request: r}
+	}
+}
+
+func hashed(t *testing.T, values ...string) func() (Redactor, error) {
+	t.Helper()
+	var vs [][]byte
+	for _, v := range values {
+		vs = append(vs, []byte(v))
+	}
+	r, err := vault.NewHashRedactor(vs)
+	if err != nil {
+		t.Fatal(err)
+	}
+	return func() (Redactor, error) { return r, nil }
+}
+
+func TestHolderRouteHoldsNoSecret(t *testing.T) {
+	keyA, keyB := synthetic(t, "sk-canary-a-"), synthetic(t, "sk-canary-b-")
+	fh := &fakeHolder{reply: holderReply(200, http.Header{"Content-Type": {"application/json"}, "X-Request-Id": {keyB}},
+		`{"echo":"`+keyB+`"}`)}
+	audit := &auditLog{}
+	p, err := New(Config{
+		Adapters:  []Adapter{OpenAI("openai-key")},
+		Grants:    map[string][]string{"m1": {"openai"}},
+		Redaction: hashed(t, keyA, keyB),
+		Holders:   map[string]http.RoundTripper{"openai-key": fh},
+		Audit:     audit,
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	w := httptest.NewRecorder()
+	p.Handler("m1").ServeHTTP(w, chat("/openai/v1/chat/completions"))
+	if w.Code != 200 {
+		t.Fatalf("status %d: %s", w.Code, w.Body)
+	}
+	if len(fh.seen) != 1 {
+		t.Fatalf("holder saw %d requests", len(fh.seen))
+	}
+	up := fh.seen[0]
+	if up.URL.Path != "/v1/chat/completions" || up.Method != "POST" {
+		t.Fatalf("holder got %s %s", up.Method, up.URL)
+	}
+	if up.Header.Get("Authorization") != "" {
+		t.Fatalf("egress sent a credential header to the holder: %q", up.Header.Get("Authorization"))
+	}
+	if leaked(w, keyB) || !strings.Contains(w.Body.String(), vault.Placeholder) {
+		t.Fatalf("account B's key reached the guest: %s %v", w.Body, w.Header())
+	}
+
+	// A journaled path carrying a vault value is redacted too.
+	req := chat("/openai/v1/" + keyA)
+	p.Handler("m1").ServeHTTP(httptest.NewRecorder(), req)
+	if ev := audit.last(t); strings.Contains(ev.Path, keyA) || !strings.Contains(ev.Path, vault.Placeholder) {
+		t.Fatalf("journaled path %q", ev.Path)
+	}
+}
+
+// A holder's drop of an exchange response stops the route exactly as the
+// proxy's own swap failure would (CRED-5t); its refusal status does too.
+func TestHolderDropStopsTheRoute(t *testing.T) {
+	for _, tc := range []struct {
+		status int
+		drop   string
+		reason string
+		stops  bool
+	}{
+		{http.StatusBadGateway, DropUnswappable, ReasonUnswappable, true},
+		{http.StatusBadGateway, DropExchangeError, "credential exchange answered with an error; dropped", false},
+		{http.StatusUnauthorized, "", ReasonLoginRefused, true},
+	} {
+		h := http.Header{}
+		if tc.drop != "" {
+			h.Set(HolderDropHeader, tc.drop)
+		}
+		fh := &fakeHolder{reply: holderReply(tc.status, h, "")}
+		fails := &failures{}
+		audit := &auditLog{}
+		p, err := New(Config{
+			Adapters:    []Adapter{planAdapter()},
+			Grants:      map[string][]string{"w1": {"plan"}},
+			Redaction:   hashed(t),
+			Holders:     map[string]http.RoundTripper{"openai-key": fh},
+			Audit:       audit,
+			RouteFailed: fails.told,
+		})
+		if err != nil {
+			t.Fatal(err)
+		}
+		w := httptest.NewRecorder()
+		p.Handler("w1").ServeHTTP(w, refresh())
+		if w.Code < 400 || audit.last(t).Reason != tc.reason {
+			t.Fatalf("%+v: status %d reason %q", tc, w.Code, audit.last(t).Reason)
+		}
+		_, stopped := p.stopped("plan")
+		if stopped != tc.stops {
+			t.Fatalf("%+v: stopped %v", tc, stopped)
+		}
+	}
+}
+
+// A swapped exchange response from the holder reaches the guest as is.
+func TestHolderSwappedExchangeIsForwarded(t *testing.T) {
+	body := `{"access_token":"placeholder-a","refresh_token":"placeholder-r","expires_in":3600,"token_type":"Bearer"}`
+	fh := &fakeHolder{reply: holderReply(200, http.Header{"Content-Type": {"application/json"}}, body)}
+	p, err := New(Config{
+		Adapters:    []Adapter{planAdapter()},
+		Grants:      map[string][]string{"w1": {"plan"}},
+		Redaction:   hashed(t),
+		Holders:     map[string]http.RoundTripper{"openai-key": fh},
+		Audit:       &auditLog{},
+		RouteFailed: (&failures{}).told,
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	w := httptest.NewRecorder()
+	p.Handler("w1").ServeHTTP(w, refresh())
+	if w.Code != 200 || !bytes.Equal(bytes.TrimSpace(w.Body.Bytes()), []byte(body)) {
+		t.Fatalf("status %d body %s", w.Code, w.Body)
+	}
+}
+
+// Holders are all or nothing: a proxy given only hashes cannot serve an
+// adapter whose credential it would have to read.
+func TestNewRequiresAHolderForEveryAdapterWithoutTheVault(t *testing.T) {
+	if _, err := New(Config{Adapters: []Adapter{OpenAI("k")}, Redaction: hashed(t), Audit: &auditLog{}}); err == nil {
+		t.Fatal("adapter without a holder accepted")
+	}
+	if _, err := New(Config{Adapters: []Adapter{OpenAI("k")}, Audit: &auditLog{}}); err == nil {
+		t.Fatal("no vault and no redaction accepted")
+	}
+	if _, err := New(Config{Adapters: []Adapter{OpenAI("k")}, Holders: map[string]http.RoundTripper{"k": &fakeHolder{}}, Vault: emptyVault{}, Redaction: hashed(t), Audit: &auditLog{}}); err == nil {
+		t.Fatal("vault beside holders accepted")
+	}
+}
diff --git a/broker/egress/proxy.go b/broker/egress/proxy.go
index c962676e6..9d0d2bf29 100644
--- a/broker/egress/proxy.go
+++ b/broker/egress/proxy.go
@@ -63,6 +63,14 @@ type Event struct {
 // denials (ADP-10), and a proxy that could drop them is refused.
 type Auditor interface{ Egress(Event) }

+// Redactor redacts vault values from agent-bound bytes: *vault.Redactor,
+// which holds the values, or *vault.HashRedactor, which holds only keyed
+// hashes of them (SIM-split).
+type Redactor interface {
+	Redact([]byte) []byte
+	Writer(io.Writer) *vault.Writer
+}
+
 // Secrets is the part of the vault the proxy uses.
 type Secrets interface {
 	Secret(name string) (vault.Secret, bool)
@@ -82,8 +90,22 @@ type Config struct {
 	Adapters []Adapter
 	// Grants maps an agent machine to the adapters it may use.
 	Grants map[string][]string
-	Vault  Secrets
-	Audit  Auditor
+	// Vault gives the proxy the credentials it injects. It is nil when
+	// every adapter has a holder (SIM-split): then the proxy reads no
+	// secret, and Redaction is required instead.
+	Vault Secrets
+	// Holders maps a credential name to the RoundTripper of the holder
+	// process that keeps it (SIM-split). The proxy sends the holder the
+	// checked request with no credential; the holder injects its own,
