+package holder
+
+import (
+	"bufio"
+	"bytes"
+	"context"
+	"crypto/tls"
+	"crypto/x509"
+	"encoding/pem"
+	"fmt"
+	"net"
+	"net/http"
+	"net/http/httptest"
+	"os"
+	"os/exec"
+	"path/filepath"
+	"strconv"
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/ghbmrk/agentos/broker/egress"
+	"github.com/ghbmrk/agentos/broker/vault"
+)
+
+// REQ: CRED-1, CRED-7
+
+// The process split, end to end (SIM-split): a "world" process stands in
+// for the unlock step and the provider, a holder process keeps the login,
+// and this test process is egress. Egress serves a guest request through
+// the holder, never holds the login (its memory is scanned for it), and
+// the holder gets its login back from the keeper after a restart.
+
+const roleEnv = "AGENTOS_HOLDER_TEST_ROLE"
+
+func TestMain(m *testing.M) {
+	switch os.Getenv(roleEnv) {
+	case "world":
+		world(os.Getenv("AGENTOS_HOLDER_TEST_DIR"))
+		return
+	case "holder":
+		holderChild(os.Getenv("AGENTOS_HOLDER_TEST_DIR"))
+		return
+	}
+	os.Exit(m.Run())
+}
+
+func fail(err error) {
+	fmt.Fprintln(os.Stderr, err)
+	os.Exit(1)
+}
+
+func freshCanary(prefix string) []byte {
+	return []byte(prefix + strconv.FormatInt(time.Now().UnixNano(), 36) + fmt.Sprintf("%x", os.Getpid()) + "q7Zr0vWm3Lk9")
+}
+
+// world runs the provider and the keeper. The login is made here and
+// leaves only to the holder, over the hand socket.
+func world(dir string) {
+	login := freshCanary("sk-canary-")
+	control := freshCanary("sk-control-")
+	prov := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if r.Header.Get("Authorization") != "Bearer "+string(login) {
+			http.Error(w, "bad login", http.StatusUnauthorized)
+			return
+		}
+		w.Header().Set("Content-Type", "application/json")
+		fmt.Fprintf(w, `{"echo":"%s"}`, login)
+	}))
+	prov.StartTLS()
+	cert := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: prov.Certificate().Raw})
+	// Egress redacts every vault value; the scan uses one probe for the
+	// login and one for the control.
+	files := map[string][]byte{
+		"provider": []byte(prov.Listener.Addr().String()),
+		"cert.pem": cert,
+		"control":  control,
+	}
+	for name, vals := range map[string][][]byte{
+		"redactor":      {login, control},
+		"probe-login":   {login},
+		"probe-control": {control},
+	} {
+		r, err := vault.NewHashRedactor(vals)
+		if err != nil {
+			fail(err)
+		}
+		files[name], _ = r.MarshalBinary()
+	}
+	for name, b := range files {
+		if err := os.WriteFile(filepath.Join(dir, name), b, 0o600); err != nil {
+			fail(err)
+		}
+	}
+	if err := os.WriteFile(filepath.Join(dir, "ready"), nil, 0o600); err != nil {
+		fail(err)
+	}
+	k := &Keeper{Socket: filepath.Join(dir, HandSocket), Secret: func() ([]byte, error) {
+		return append([]byte(nil), login...), nil
+	}, Every: 20 * time.Millisecond}
+	k.Run(context.Background())
+}
+
+// holderChild is the holder process: it trusts the world's provider and
+// dials it for the adapter's host.
+func holderChild(dir string) {
+	addr, err := os.ReadFile(filepath.Join(dir, "provider"))
+	if err != nil {
+		fail(err)
+	}
+	cert, err := os.ReadFile(filepath.Join(dir, "cert.pem"))
+	if err != nil {
+		fail(err)
+	}
+	pool := x509.NewCertPool()
+	pool.AppendCertsFromPEM(cert)
+	tr := &http.Transport{
+		DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
+			var d net.Dialer
+			return d.DialContext(ctx, "tcp", string(addr))
+		},
+		TLSClientConfig: &tls.Config{RootCAs: pool, ServerName: "example.com"},
+	}
+	h, err := New(Config{Adapters: []egress.Adapter{egress.OpenAI("openai-key")}, Transport: tr})
+	if err != nil {
+		fail(err)
+	}
+	reqs, err := Listen(filepath.Join(dir, RequestSocket), os.Getuid())
+	if err != nil {
+		fail(err)
+	}
+	hand, err := Listen(filepath.Join(dir, HandSocket), os.Getuid())
+	if err != nil {
+		fail(err)
+	}
+	fail(h.Serve(reqs, hand))
+}
+
+func start(t *testing.T, role, dir string) *exec.Cmd {
+	t.Helper()
+	c := exec.Command(os.Args[0], "-test.run=^$")
+	c.Env = append(os.Environ(), roleEnv+"="+role, "AGENTOS_HOLDER_TEST_DIR="+dir)
+	c.Stderr = os.Stderr
+	if err := c.Start(); err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { c.Process.Kill(); c.Wait() })
+	return c
+}
+
+func waitFor(t *testing.T, what string, ok func() bool) {
+	t.Helper()
+	deadline := time.Now().Add(10 * time.Second)
+	for !ok() {
+		if time.Now().After(deadline) {
+			t.Fatalf("timed out waiting for %s", what)
+		}
+		time.Sleep(20 * time.Millisecond)
+	}
+}
+
+type journal struct{ events []egress.Event }
+
+func (j *journal) Egress(e egress.Event) { j.events = append(j.events, e) }
+
+func TestEgressHoldsNoLoginAcrossProcesses(t *testing.T) {
+	if testing.Short() {
+		t.Skip("starts processes")
+	}
+	dir := socketDir(t)
+	start(t, "world", dir)
+	waitFor(t, "the world", func() bool { _, err := os.Stat(filepath.Join(dir, "ready")); return err == nil })
+	holder := start(t, "holder", dir)
+
+	red := loadRedactor(t, dir, "redactor")
+	p, err := egress.New(egress.Config{
+		Adapters:  []egress.Adapter{egress.OpenAI("openai-key")},
+		Grants:    map[string][]string{"m1": {"openai"}},
+		Redaction: func() (egress.Redactor, error) { return red, nil },
+		Holders:   map[string]http.RoundTripper{"openai-key": Client(filepath.Join(dir, RequestSocket))},
+		Audit:     &journal{},
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	ask := func() *httptest.ResponseRecorder {
+		r := httptest.NewRequest("POST", "/openai/v1/chat/completions", strings.NewReader(`{"model":"m","messages":[]}`))
+		r.Header.Set("Content-Type", "application/json")
+		r.Header.Set("Authorization", "Bearer placeholder")
+		w := httptest.NewRecorder()
+		p.Handler("m1").ServeHTTP(w, r)
+		return w
+	}
+	var w *httptest.ResponseRecorder
+	waitFor(t, "the first answer", func() bool { w = ask(); return w.Code == 200 })
+	if !strings.Contains(w.Body.String(), vault.Placeholder) {
+		t.Fatalf("answer %s", w.Body)
+	}
+
+	// Egress's memory, after serving, holds no form of the login. The scan
+	// is a hashed redactor over the login alone: a match adds a
+	// placeholder. Its control is the same scan for a value this process
+	// did read.
+	control, err := os.ReadFile(filepath.Join(dir, "control"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if n := scanSelf(t, loadRedactor(t, dir, "probe-control")); n == 0 {
+		t.Fatal("control: the memory scan missed a value this process holds")
+	}
+	if n := scanSelf(t, loadRedactor(t, dir, "probe-login")); n != 0 {
+		t.Fatalf("egress memory holds the login: %d matches", n)
+	}
+
+	// A holder that dies takes the route down; one that restarts gets its
+	// login from the keeper, not from egress.
+	holder.Process.Kill()
+	holder.Wait()
+	if w := ask(); w.Code == 200 {
+		t.Fatalf("answered with the holder down: %s", w.Body)
+	}
+	start(t, "holder", dir)
+	waitFor(t, "the restarted holder", func() bool { return ask().Code == 200 })
+	_ = control[0]
+}
+
+func loadRedactor(t *testing.T, dir, name string) *vault.HashRedactor {
+	t.Helper()
+	enc, err := os.ReadFile(filepath.Join(dir, name))
+	if err != nil {
+		t.Fatal(err)
+	}
+	var r vault.HashRedactor
+	if err := r.UnmarshalBinary(enc); err != nil {
+		t.Fatal(err)
+	}
+	return &r
+}
+
+// scanSelf reads every writable mapping of this process and returns how
+// many spans r redacts in it.
+func scanSelf(t *testing.T, r *vault.HashRedactor) int {
+	t.Helper()
+	maps, err := os.Open("/proc/self/maps")
+	if err != nil {
+		t.Skip("no /proc/self/maps")
+	}
+	defer maps.Close()
+	mem, err := os.Open("/proc/self/mem")
+	if err != nil {
+		t.Skip("no /proc/self/mem")
+	}
+	defer mem.Close()
+	const chunk = 1 << 20
+	over := r.MaxLen()
+	buf := make([]byte, chunk+over)
+	ph := []byte(vault.Placeholder)
+	found := 0
+	sc := bufio.NewScanner(maps)
+	for sc.Scan() {
+		f := strings.Fields(sc.Text())
+		if len(f) < 2 || !strings.HasPrefix(f[1], "rw") {
+			continue
+		}
+		if len(f) >= 6 && (f[5] == "[vvar]" || f[5] == "[vsyscall]") {
+			continue
+		}
+		var lo, hi uint64
+		if _, err := fmt.Sscanf(f[0], "%x-%x", &lo, &hi); err != nil {
+			continue
+		}
+		for at := lo; at < hi; at += chunk {
+			n := uint64(len(buf))
+			if at+n > hi {
+				n = hi - at
+			}
+			got, err := mem.ReadAt(buf[:n], int64(at))
+			if got == 0 && err != nil {
+				break
+			}
+			b := buf[:got]
+			if allZero(b) {
+				continue
+			}
+			if d := bytes.Count(r.Redact(b), ph) - bytes.Count(b, ph); d > 0 {
+				found += d
+			}
+		}
+	}
+	return found
+}
+
+func allZero(b []byte) bool {
+	for _, c := range b {
+		if c != 0 {
+			return false
+		}
+	}
+	return true
+}
diff --git a/broker/vault/hashredact.go b/broker/vault/hashredact.go
new file mode 100644
index 000000000..3022f035d
--- /dev/null
+++ b/broker/vault/hashredact.go
@@ -0,0 +1,273 @@
+package vault
+
+import (
+	"crypto/hmac"
+	"crypto/rand"
+	"crypto/sha256"
+	"encoding/binary"
+	"encoding/json"
+	"errors"
+	"io"
+)
+
+// HashWindow is the length, in bytes, of the windows a HashRedactor keeps
+// keyed hashes of. A form shorter than it is hashed whole.
+const HashWindow = 24
+
+// HashRedactor redacts vault values without holding them (SIM-split). It
+// is built where the plaintext is (the unlock step) and handed to egress,
+// which then redacts every account's values on every response and
+// journaled path while holding only keyed hashes (CRED-7). For each form a
+// Redactor matches (encodings), it keeps a keyed hash of the head window
+// and of the tail window, and of the whole form: a head hit followed by
+// the whole form redacts the whole form, and a head or tail hit alone (a
+// truncated echo) redacts the window. Only two windows per form are kept,
+// so overlapping windows cannot be chained to recover a value byte by
+// byte. A rolling fingerprint with a secret base finds candidate spans;
+// each is confirmed by HMAC-SHA-256 before it is redacted.
+type HashRedactor struct {
+	key    []byte
+	base   uint64
+	probes []*probe
+	maxLen int
+}
+
+// probe is every hashed window of one length, in one case mode.
+type probe struct {
+	n    int
+	fold bool
+	pow  uint64 // base^n
+	hits map[uint32][]hashHit
+}
+
+type hashHit struct {
+	sum [16]byte
+	// full is the whole form's length when this window is its head, and
+	// fullSum its hash; zero when the window stands alone.
+	full    int
+	fullSum [16]byte
+}
+
+// NewHashRedactor builds a redactor over values that keeps no part of
+// them. Empty values are ignored.
+func NewHashRedactor(values [][]byte) (*HashRedactor, error) {
+	key := make([]byte, 32)
+	var b [8]byte
+	if _, err := rand.Read(key); err != nil {
+		return nil, err
+	}
+	if _, err := rand.Read(b[:]); err != nil {
+		return nil, err
+	}
+	r := &HashRedactor{key: key, base: binary.LittleEndian.Uint64(b[:]) | 1}
+	for _, p := range encodings(values) {
+		form := p.b
+		if len(form) < HashWindow {
+			r.add(hashEntry{N: len(form), Fold: p.fold, Pre: r.print(form), Sum: r.mac(form)})
+			continue
+		}
+		head, tail := form[:HashWindow], form[len(form)-HashWindow:]
+		r.add(hashEntry{N: HashWindow, Fold: p.fold, Pre: r.print(head), Sum: r.mac(head), Full: len(form), FullSum: r.mac(form)})
+		r.add(hashEntry{N: HashWindow, Fold: p.fold, Pre: r.print(tail), Sum: r.mac(tail)})
+	}
+	return r, nil
+}
+
+// hashEntry is one hashed window, and its wire form.
+type hashEntry struct {
+	N       int    `json:"n"`
+	Fold    bool   `json:"f,omitempty"`
+	Pre     uint32 `json:"p"`
+	Sum     []byte `json:"s"`
+	Full    int    `json:"l,omitempty"`
+	FullSum []byte `json:"ls,omitempty"`
+}
+
+func (r *HashRedactor) add(e hashEntry) {
+	var pr *probe
+	for _, q := range r.probes {
+		if q.n == e.N && q.fold == e.Fold {
+			pr = q
+		}
+	}
+	if pr == nil {
+		pow := uint64(1)
+		for i := 0; i < e.N; i++ {
+			pow *= r.base
+		}
+		pr = &probe{n: e.N, fold: e.Fold, pow: pow, hits: map[uint32][]hashHit{}}
+		r.probes = append(r.probes, pr)
+	}
+	h := hashHit{full: e.Full}
+	copy(h.sum[:], e.Sum)
+	copy(h.fullSum[:], e.FullSum)
+	pr.hits[e.Pre] = append(pr.hits[e.Pre], h)
+	for _, n := range []int{e.N, e.Full} {
+		if n > r.maxLen {
+			r.maxLen = n
+		}
+	}
+}
+
+func (r *HashRedactor) mac(b []byte) []byte {
+	m := hmac.New(sha256.New, r.key)
+	m.Write(b)
+	return m.Sum(nil)[:16]
+}
+
+// print is the rolling fingerprint of b: its top 32 bits only.
+func (r *HashRedactor) print(b []byte) uint32 {
+	var h uint64
+	for _, c := range b {
+		h = h*r.base + uint64(c) + 1
+	}
+	return uint32(h >> 32)
+}
+
+// MaxLen is the longest span the redactor can match, in bytes.
+func (r *HashRedactor) MaxLen() int { return r.maxLen }
+
+// Redact returns b with every match replaced by Placeholder.
+func (r *HashRedactor) Redact(b []byte) []byte {
+	out, rest := r.scan(nil, b, true)
+	return append(out, rest...)
+}
+
+// Writer returns a writer that redacts a stream on its way to w, holding
+// back at most MaxLen()-1 bytes; Close writes them. Close does not close w.
+func (r *HashRedactor) Writer(w io.Writer) *Writer { return &Writer{r: r, w: w} }
+
+// scan is Redactor.scan's contract: when final is false, no match is
+// decided at a position whose longest possible span could still run past
+// b, so the result does not depend on how a stream was split.
+func (r *HashRedactor) scan(out, b []byte, final bool) (_, rest []byte) {
+	limit := len(b)
+	if !final && r.maxLen > 0 {
+		limit = len(b) - (r.maxLen - 1)
+	}
+	var plain, lower []uint64
+	var low []byte
+	pos := 0
+	for i := 0; i < limit; i++ {
+		best := 0
+		for _, pr := range r.probes {
+			if i+pr.n > len(b) {
+				continue
+			}
+			hay, pre := b, &plain
+			if pr.fold {
+				if low == nil {
+					low = asciiLower(b)
+				}
+				hay, pre = low, &lower
+			}
+			if *pre == nil {
+				*pre = r.prefix(hay)
+			}
+			h := (*pre)[i+pr.n] - (*pre)[i]*pr.pow
+			hits := pr.hits[uint32(h>>32)]
+			if len(hits) == 0 {
+				continue
+			}
+			sum := r.mac(hay[i : i+pr.n])
+			for _, hit := range hits {
+				if !hmac.Equal(sum, hit.sum[:]) {
+					continue
+				}
+				n := pr.n
+				if hit.full > 0 && i+hit.full <= len(b) && hmac.Equal(r.mac(hay[i:i+hit.full]), hit.fullSum[:]) {
+					n = hit.full
+				}
+				if n > best {
+					best = n
+				}
+			}
+		}
+		if best > 0 {
+			out = append(out, b[pos:i]...)
+			out = append(out, Placeholder...)
+			pos = i + best
+			i = pos - 1
+		}
+	}
+	if final {
+		return append(out, b[pos:]...), nil
+	}
+	keep := limit
+	if keep < pos {
+		keep = pos
+	}
+	if keep < 0 {
+		keep = 0
+	}
+	return append(out, b[pos:keep]...), b[keep:]
+}
+
+// prefix returns the rolling prefix fingerprints of b, so any window's
+// fingerprint is two lookups.
+func (r *HashRedactor) prefix(b []byte) []uint64 {
+	h := make([]uint64, len(b)+1)
+	for i, c := range b {
+		h[i+1] = h[i]*r.base + uint64(c) + 1
+	}
+	return h
+}
+
+type hashWire struct {
+	Key     []byte      `json:"k"`
+	Base    uint64      `json:"b"`
+	Entries []hashEntry `json:"e"`
+}
+
+// MarshalBinary encodes the redactor for the hand from the unlock step to
+// egress. The encoding holds keyed hashes and the key, never a value.
+func (r *HashRedactor) MarshalBinary() ([]byte, error) {
+	w := hashWire{Key: r.key, Base: r.base}
+	for _, pr := range r.probes {
+		for pre, hits := range pr.hits {
+			for _, h := range hits {
+				e := hashEntry{N: pr.n, Fold: pr.fold, Pre: pre, Sum: append([]byte(nil), h.sum[:]...), Full: h.full}
+				if h.full > 0 {
+					e.FullSum = append([]byte(nil), h.fullSum[:]...)
+				}
+				w.Entries = append(w.Entries, e)
+			}
+		}
+	}
+	return json.Marshal(w)
+}
+
+// UnmarshalBinary replaces r with the encoded redactor.
+func (r *HashRedactor) UnmarshalBinary(b []byte) error {
+	var w hashWire
+	if err := json.Unmarshal(b, &w); err != nil {
+		return err
+	}
+	if len(w.Key) != 32 || w.Base&1 == 0 {
+		return errors.New("vault: bad hash redactor key")
+	}
+	n := &HashRedactor{key: w.Key, base: w.Base}
+	for _, e := range w.Entries {
+		if e.N < 4 || e.N > HashWindow || len(e.Sum) != 16 ||
+			(e.Full != 0 && (e.Full <= e.N || len(e.FullSum) != 16)) {
+			return errors.New("vault: bad hash redactor entry")
+		}
+		n.add(e)
+	}
+	*r = *n
+	return nil
+}
+
+// HashRedactor builds a HashRedactor over every entry.
+func (v *Vault) HashRedactor() (*HashRedactor, error) {
+	v.mu.RLock()
+	defer v.mu.RUnlock()
+	if v.closed {
+		return nil, ErrClosed
+	}
+	vals := make([][]byte, 0, len(v.entries))
+	for _, r := range v.entries {
+		vals = append(vals, r.Value)
+	}
+	return NewHashRedactor(vals)
+}
